```jsx
import React, { useState, useEffect } from 'react';
import { observer } from 'mobx-react';
import { createContext } from './store';

const CreateObjectModel = createContext();

export const CreateObjectView = ({ model }) => {
  const [asset, setAsset] = useState('');

  useEffect(() => {
    const cleanup = () => {
      model.cleanupScene();
    };

    return cleanup;
  }, []);

  const handleSubmit = () => {
    if (asset) {
      model.createObject(asset).then(() => {
        model.setSelectedAsset(asset);
      });
    }
  };

  const handleChange = e => {
    setAsset(e.target.value);
  };

  return (
    <CreateObjectModel.Provider value={model}>
      <form onSubmit={handleSubmit}>
        <label htmlFor="asset">Asset:</label>
        <input type="text" id="asset" name="asset" value={asset} onChange={handleChange} />
        <button type="submit">Create object</button>
        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
          {model.availableAssets.map(asset => (
            <div key={asset} id={`asset-${asset}`} className="asset-wrapper">
              <img src={asset} alt={asset} width="100" height="100" />
              <p>{asset}</p>
            </div>
          ))}
        </div>
        <button id="cleanup-scene" onClick={model.cleanupScene}>Cleanup scene</button>
      </form>
    </CreateObjectModel.Provider>
  );
};

CreateObjectView.displayName = 'CreateObjectView';

export default observer(CreateObjectView);
```

