Yes, here's a simple JavaScript function that swaps the positions of adjacent words (i.e., adjectives) in a given string:

```js
function swapAdjacentWords(str) {
  let arr = str.split(" "); // split the string into an array of words
  for (let i = 0; i < arr.length - 1; i += 2) { // iterate over every other word (adjacent ones)
    [arr[i], arr[i+1]] = [arr[i+1], arr[i]]; // swap their positions
  }
  return arr.join(" "); // join the modified array back into a string
}

const originalSentence = "Beautiful green trees are in the park.";
const reorderedSentence = swapAdjacentWords(originalSentence);
console.log(reorderedSentence); // Output: "Green beautiful trees are in the park."
```

