Here's a JavaScript function that switches the order of adjectives in a sentence:

```javascript
function switchAdjectives(sentence) {
  const parts = sentence.split(/(\w+\s*\w+)/); // split by adjective groups

  let reversedParts = [];

  for (let i = parts.length - 1; i >= 0; i--) {
    reversedParts.push(parts[i].trim()); // trim whitespace at ends
    const adjectives = parts[i].split(' '); // split into individual words
    reversedParts.push(...adjectives.reverse().join(' ')); // reverse and join back
  }

  return reversedParts.join(' ');
}

