```

Here's an example implementation:

```cpp
#include <iostream>
#include <cstdlib>

int main() {
    double purchasePrice = 1000;
    double residualValue = 200;
    double refundAmount = 600;
    double totalValue = purchasePrice - residualValue;
    double percentageOfRefund;

    if (refundAmount > totalValue) {
        refundAmount = totalValue;
    }
    percentageOfRefund = static_cast<double>(refundAmount) / purchasePrice * 100;

    std::cout << "The agreed-upon refund is £" << refundAmount << " (" << percentageOfRefund << "%).";
    return EXIT_SUCCESS;
}
