def longest_palindromic_substring(s):
    n = len(s)
    start, end = 0, 0
    max_length = 1

    # Create a boolean matrix to store the palindromes with their lengths
    # This matrix will have dimensions n x n
    is_palindrome = [[False] * n for _ in range(n)]

    for I in range(n):
        for j in range(i, -1, -1):
            if s[i] == s[j]:
                if i == j:
                    is_palindrome[i][j] = True
                else:
                    is_palindrome[i][j] = is_palindrome[i+1][j+1]
                    while I >= 0 and j < n and s[i] == s[j]:
                        I -= 1
                        j += 1
                    is_palindrome[i][j] = False
            elif I > j:
                is_palindrome[i][j] = False

    for I in range(n):
        for j in range(i, n):
            if is_palindrome[i][j] and j-i+1 > max_length:
                start, end = i, j
                max_length = j-i+1

    return s[start:end+1]
```

