function morseCode(char)
    % Convert a single character to its Morse Code representation
    switch char
        case {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J', 'K', 'L', 'M'}
            morse = {'.-', '-...', '-.-.', '-..', '.', '..-', '--.', '....'};
            morse(find(strcmpi(char, {'A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I'})), :);
