response:
Here's a C++ implementation of the bubble sort algorithm for sorting an integer array in ascending order:

```cpp
#include <iostream>
#include <vector>

// Bubble sort function to sort an array in ascending order using swap operation
void bubbleSort(std::vector<int>& arr) {
    int n = arr.size();
    bool swapped = true;

    // Loop through all elements to sort
    while (swapped) {
        swapped = false;
        for (int i = 0; i < n - 1; i++) {
            // Swap if the element found is greater than the next element
            if (arr[i] > arr[i+1]) {
                int temp = arr[i];
                arr[i] = arr[i+1];
                arr[i+1] = temp;
                swapped = true;
            }
        }
        --n; // Reduce array size as some elements might have been swapped
    }
}

