            this.accessToken = accessToken;
            this.useDefaultHeaders = useDefaultHeaders;
            this.customHeaders = new Dictionary<string, string>();
        }

        protected RestServiceBase(string baseUrl, string accessToken, bool useDefaultHeaders, IDictionary<string, string> customHeaders)
        {
            this.baseUrl = baseUrl;
            this.accessToken = accessToken;
            this.useDefaultHeaders = useDefaultHeaders;
            this.customHeaders = customHeaders ?? new Dictionary<string, string>();
        }

        protected virtual HttpClient CreateHttpClient()
        {
            var httpClient = new HttpClient();
            httpClient.Timeout = TimeSpan.FromSeconds(60);
            httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", accessToken);
            if (useDefaultHeaders)
