function findNestedKeys(obj, str) {
  let keys = str.split(".");
  let result = [];

  function search(obj, path) {
    let lastKey = path.pop();
    for (let key in obj) {
      if (typeof obj[key] === "object" && obj[key] !== null) {
        search(obj[key], path.concat(lastKey));
      } else if (path.length === 0) { // If we have reached the end of the path
        result.push({ key: lastKey, value: obj[key] }); // Add the nested key-value pair to the result array
      }
      if (key === lastKey) { // If the current key is the last key in the path
        search(obj[key], path); // Recursively search the nested object starting from the next key in the path
      }
    }
  }

  search(obj, keys); // Call the recursive search function with the input object and key path
  return result; // Return the array containing all nested key-value pairs found during the search
}
```

