```php
<?php
// Set up the timezone
$tz = new DateTimeZone('America/New_York');
$now = new DateTime('now', $tz);

// Define day and night times
$dayStart = new DateTime('07:00:00', $tz);
$nightEnd = new DateTime('23:00:00', $tz);

// Is it currently daytime or nighttime?
if ($now->getTimestamp() >= $dayStart->getTimestamp() && $now->getTimestamp() <= $nightEnd->getTimestamp()) {
    // It's daytime!
    echo '<div id="sun" class="day"></div>';
} else {
    // It's nighttime or sunrise/sunset
    echo '<div id="sun" class="night"></div>';
}
?>

