```javascript
// Initialize Firebase app and messaging service
const firebaseConfig = {...};
firebase.initializeApp(firebaseConfig);
const messaging = firebase.messaging();

// Request permission to send push notifications
messaging.requestPermission()
  .then(() => console.log('Authorization status:', messaging.authorizationStatus))
  .catch((err) => console.log('Unable to get permission to notify.', err));

// Handle incoming push notifications
messaging.onMessage((payload) => {
  const notificationTitle = payload.notification.title;
  const notificationOptions = {
    body: payload.notification.body,
    icon: payload.notification.icon,
    click_action: payload.notification.click_action,
  };
  const notification = new Notification(notificationTitle, notificationOptions);
});

// Send push notification to specific user
function sendNotification(userId) {
  const payload = {
    notification: {
      title: 'Fitness Reminder',
      body: 'Complete your daily workout now!',
      click_action: '/workout',
      icon: 'https://example.com/favicon.ico',
    },
    to: userId,
    apns: {
      headers: {
        'apns-push-type': 'background',
      },
    },
  };
  return messaging.send(payload).then((response) => {
    console.log('Successfully sent message:', response);
  }).catch((error) => {
    console.log('Error sending message:', error);
  });
}
```

