```jsx
import React, { useState, useEffect } from 'react';
import { View, Text, StyleSheet, Platform } from 'react-native';
import { PushNotificationIOS, PermissionStatusIOS } from '@react-native-community/push-notification-ios';
import { Notifications } from 'expo';

export default function App() {
  const [notifications, setNotifications] = useState([]);

  // Request permission to send push notifications
  useEffect(() => {
    requestUserPermission();
  }, []);

  const requestUserPermission = async () => {
    const permissionStatus = await PermissionsAndroid.request(
      PermissionsAndroid.PERMISSIONS.CAMERA,
      {
        title: 'Permission to access camera',
        message: 'We need your permission to access your camera',
        buttonNeutral: 'Ask Me Later',
        buttonNegative: 'Cancel',
        buttonPositive: 'OK',
      },
    );

    // Handle permission grant or denial
    switch (permissionStatus) {
      case PermissionsAndroid.RESULTS.GRANTED:
        console.log('Camera permission granted');
        break;
      case PermissionsAndroid.RESULTS.DENIED:
        console.log('Camera permission denied');
        break;
      case PermissionsAndroid.RESULTS.NEVER_ASK_AGAIN:
        console.log('Camera permission revoked');
        break;
      default:
        break;
    }
  };

  // Listen for incoming push notifications
  useEffect(() => {
    const subscription = Notifications.addListener((notification) => {
      setNotifications([...notifications, notification]);
    });

    return () => {
      subscription.remove();
    };

