To retrieve the username from the JSON Web Token (JWT) in an ASP.NET Core WebAPI, you can follow these steps:

1. Install the `Microsoft.IdentityModel.Tokens` package using the following command in your project's terminal or command prompt:

   ```console
   dotnet add package Microsoft.IdentityModel.Tokens
   ```

2. Add the `[Authorize]` attribute to your controller methods to ensure that only authenticated users can access them. This will automatically validate the JWT token and extract the claims.

3. Create a middleware to validate the JWT token on every request. Here is an example implementation:

   ```csharp
   public void Configure(IApplicationBuilder app)
   {
       // ...

       app.UseMiddleware<JwtMiddleware>();

       // ...
   }

   public class JwtMiddleware
   {
       private readonly RequestDelegate _next;
       private readonly IConfiguration _configuration;

       public JwtMiddleware(RequestDelegate next, IConfiguration configuration)
       {
           _next = next;
           _configuration = configuration;
       }

       public async Task InvokeAsync(HttpContext httpContext)
       {
           var authorization = httpContext.Request.Headers["Authorization"];
           if (!string.IsNullOrWhiteSpace(authorization))
           {
               var bearerToken = authorization.Split(" ", StringSplitOptions.RemoveEmptyEntries)[1];
               try
               {
                   var tokenHandler = new JwtSecurityTokenHandler();
                   var key = Encoding.ASCII.Parse(_configuration["Jwt:SecretKey"]);
                   var securityToken = tokenHandler.ReadJwtToken(bearerToken);
                   var username = securityToken.Claims.FirstOrDefault(x => x.Type == ClaimTypes.Name)?.Value;
                   httpContext.Items["Username"] = username;
               }
               catch
               {
                   httpContext.Response.StatusCode = StatusCodes.Status401Unauthorized;
                   return;
               }
           }

           await _next(httpContext);
       }
   }
   ```

