import { ExecutionContext, Injectable, NestMiddleware } from '@nestjs/common';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';

@Injectable()
export class EnvGuard implements NestMiddleware {
  public use(handler: Function): Function {
    return function (...args) {
      return this.wrapHandler(handler).bind(this)(...args);
    };
  }

  private wrapHandler(handler: Function): Function {
    return function (...args) {
      const context: ExecutionContext = args[0];
      const req = context.switchToHttp().getRequest();
