if (($sock = stream_socket_server("tcp://$host:$port", $errCode, $errStr)) === false) {
    echo "Could not open socket: $errStr ($errCode)\n";
    exit(1);
}

while (true) {
    $client = stream_socket_accept($sock);
    if ($client !== false) {
        // Handle incoming connections here
        // ...
        fclose($client);
    }
}

fclose($sock);
```

