function sortArray(array) {
  const length = array.length;
  for (let i = 0; i < length - 1; i++) {
    for (let j = i + 1; j < length; j++) {
      if (array[i] > array[j]) {
        [array[i], array[j]] = [array[j], array[i]];
      }
    }
  }
  return array;
}

const arr = [3, 7, 2, 1, 6];
const sortedArr = sortArray(arr);
console.log(sortedArr); // Output: [1, 2, 3, 6, 7]
