# Define function for checking SID history
function CheckSidHistory($sid) {
    $domain = (Get-ADDomain).Name
    $searcher = New-Object -ComObject ADSearch
    $searcher.Filter = "(objectCategory=group)(sid=$sid)"
    $results = $searcher.Execute()

    foreach ($result in $results) {
        $membership = Get-ADGroupMember -Identity $result.SamAccountName
        foreach ($member in $membership) {
            $sidHistory = Get-ADUser -Identity $member.SamAccountName | Select-Object -ExpandProperty sidhistory
            foreach ($sidEntry in $sidHistory) {
                if ($sidEntry.Value -eq $sid) {
                    return $true
                }
            }
        }
    }

    return $false
}

